    1: //! Non-UTF-8 relative names on the wire (contract v7,
    2: //! `FileHeader.raw_relative_path`; `docs/plan/SOURCE_SIDE_CONTAINMENT.md`
    3: //! D-F, owner ruling D-2026-09-29-3 — rsync parity).
    4: //!
    5: //! The manifest identity of every file is the lossy UTF-8 text in
    6: //! `FileHeader.relative_path`. When a source name has a component that is
    7: //! not valid UTF-8, the scan ALSO carries the exact source bytes (with `/`
    8: //! separators) in `raw_relative_path`, and:
    9: //!
   10: //! * the source opens the file by those bytes, never by the lossy text
   11: //!   (which names nothing on disk);
   12: //! * a destination that can hold the bytes creates the real name;
   13: //! * a destination that cannot reports the file at manifest intake with
   14: //!   [`DESTINATION_CANNOT_STORE_REASON`] and never grants it.
   15: //!
   16: //! The bytes are never a key: every map, need, record, skip and terminator
   17: //! stays keyed by the text.
   18: 
   19: use std::ffi::OsStr;
   20: use std::path::{Path, PathBuf};
   21: 
   22: use crate::generated::FileHeader;
   23: 
   24: /// Reason recorded at manifest intake for a name the destination cannot
   25: /// store (A13). Exact wording is pinned.
   26: pub const DESTINATION_CANNOT_STORE_REASON: &str =
   27:     "source: filename is not valid UTF-8; the destination cannot store it (rename it to transfer)";
   28: 
   29: /// Reason recorded for the second of two manifest entries that collapse
   30: /// to the same text path (A13). Exact prefix is pinned; the raw bytes of
   31: /// the rejected entry follow it when known.
   32: pub const DUPLICATE_MANIFEST_PATH_REASON: &str =
   33:     "source: duplicate manifest path (lossy name collision)";
   34: 
   35: /// The exact bytes of `rel` (a relative path from the scan) joined with
   36: /// `/`, iff at least one component is not valid UTF-8. `None` for every
   37: /// representable name, so the common case costs nothing on the wire.
   38: pub fn raw_relative_bytes(rel: &Path) -> Option<Vec<u8>> {
   39:     let mut lossy = false;
   40:     let mut bytes: Vec<u8> = Vec::new();
   41:     for (i, component) in rel.components().enumerate() {
   42:         let part = component.as_os_str();
   43:         if part.to_str().is_none() {
   44:             lossy = true;
   45:         }
   46:         if i > 0 {
   47:             bytes.push(b'/');
   48:         }
   49:         bytes.extend_from_slice(part.as_encoded_bytes());
   50:     }
   51:     lossy.then_some(bytes)
   52: }
   53: 
   54: /// Whether THIS process, as a destination, can create a name from raw
   55: /// bytes: Linux and the BSDs accept any bytes; macOS (APFS/HFS+) rejects
   56: /// invalid UTF-8 with `EILSEQ`; Windows names are UTF-16 and cannot hold
   57: /// arbitrary bytes at all. The create-time errno remains the per-file
   58: /// backstop ([`is_unrepresentable_name_error`]).
   59: pub const fn destination_can_store_raw_names() -> bool {
   60:     cfg!(all(unix, not(target_os = "macos")))
   61: }
   62: 
   63: /// Whether `error` from a create/open is the filesystem refusing the
   64: /// bytes of the name itself (`EILSEQ`, or `EINVAL` from a filesystem that
   65: /// validates names) rather than an ordinary I/O failure.
   66: pub fn is_unrepresentable_name_error(error: &std::io::Error) -> bool {
   67:     #[cfg(unix)]
   68:     {
   69:         matches!(
   70:             error.raw_os_error(),
   71:             Some(code) if code == libc::EILSEQ || code == libc::EINVAL
   72:         )
   73:     }
   74:     #[cfg(not(unix))]
   75:     {
   76:         let _ = error;
   77:         false
   78:     }
   79: }
   80: 
   81: /// Rebuild the path a raw-name header names on THIS host's filesystem.
   82: /// Unix: the bytes verbatim. Windows: the bytes are the WTF-8 this same
   83: /// process's scan produced, so they round-trip exactly.
   84: pub fn path_from_raw(raw: &[u8]) -> PathBuf {
   85:     #[cfg(unix)]
   86:     {
   87:         use std::os::unix::ffi::OsStrExt as _;
   88:         PathBuf::from(OsStr::from_bytes(raw))
   89:     }
   90:     #[cfg(windows)]
   91:     {
   92:         // SAFETY: the only producer of `raw_relative_path` on a Windows
   93:         // source is `raw_relative_bytes` in this same process, which
   94:         // took the bytes from `OsStr::as_encoded_bytes`; the Windows
   95:         // destination never creates from raw bytes
   96:         // (`destination_can_store_raw_names` is false), so every byte
   97:         // string that reaches here is this host's own WTF-8 encoding.
   98:         // Split on the wire separator and rebuild with the native one.
   99:         let mut out = PathBuf::new();
  100:         for piece in raw.split(|b| *b == b'/') {
  101:             let os_piece: &OsStr = unsafe { OsStr::from_encoded_bytes_unchecked(piece) };
  102:             out.push(os_piece);
  103:         }
  104:         out
  105:     }
  106:     #[cfg(not(any(unix, windows)))]
  107:     {
  108:         PathBuf::from(String::from_utf8_lossy(raw).into_owned())
  109:     }
  110: }
  111: 
  112: /// The on-disk path of `header` under `root`: by raw bytes when the name
  113: /// is not representable as text, by the text otherwise. An empty
  114: /// relative path means "`root` is itself the file".
  115: pub fn source_path(root: &Path, header: &FileHeader) -> PathBuf {
  116:     if let Some(raw) = header.raw_relative_path.as_deref() {
  117:         return root.join(path_from_raw(raw));
  118:     }
  119:     if header.relative_path.is_empty() {
  120:         root.to_path_buf()
  121:     } else {
  122:         root.join(&header.relative_path)
  123:     }
  124: }
  125: 
  126: /// Render raw name bytes for a report: printable ASCII as-is, every other
  127: /// byte as `\xNN`, so two names that collapse to one lossy text can still
  128: /// be told apart in the failure block.
  129: pub fn escape_raw(raw: &[u8]) -> String {
  130:     let mut out = String::with_capacity(raw.len());
  131:     for &b in raw {
  132:         if (0x20..0x7f).contains(&b) && b != b'\\' {
  133:             out.push(b as char);
  134:         } else {
  135:             out.push_str(&format!("\\x{b:02x}"));
  136:         }
  137:     }
  138:     out
  139: }
  140: 
  141: #[cfg(test)]
  142: mod tests {
  143:     use super::*;
  144: 
  145:     #[test]
  146:     fn representable_names_carry_no_raw_bytes() {
  147:         assert_eq!(raw_relative_bytes(Path::new("sub/café.txt")), None);
  148:         assert_eq!(raw_relative_bytes(Path::new("")), None);
  149:     }
  150: 
  151:     #[cfg(unix)]
  152:     #[test]
  153:     fn a_non_utf8_component_carries_the_exact_bytes_with_slash_separators() {
  154:         use std::os::unix::ffi::OsStrExt as _;
  155:         let rel = Path::new(OsStr::from_bytes(b"sub/caf\xe9.txt"));
  156:         assert_eq!(raw_relative_bytes(rel), Some(b"sub/caf\xe9.txt".to_vec()));
  157:         assert_eq!(
  158:             path_from_raw(b"sub/caf\xe9.txt"),
  159:             PathBuf::from(OsStr::from_bytes(b"sub/caf\xe9.txt"))
  160:         );
  161:     }
  162: 
  163:     #[cfg(unix)]
  164:     #[test]
  165:     fn source_path_prefers_the_raw_bytes_over_the_lossy_text() {
  166:         use std::os::unix::ffi::OsStrExt as _;
  167:         let header = FileHeader {
  168:             relative_path: "sub/caf\u{fffd}.txt".into(),
  169:             raw_relative_path: Some(b"sub/caf\xe9.txt".to_vec()),
  170:             ..Default::default()
  171:         };
  172:         assert_eq!(
  173:             source_path(Path::new("/root"), &header),
  174:             PathBuf::from(OsStr::from_bytes(b"/root/sub/caf\xe9.txt"))
  175:         );
  176:         let plain = FileHeader {
  177:             relative_path: "sub/plain.txt".into(),
  178:             ..Default::default()
  179:         };
  180:         assert_eq!(
  181:             source_path(Path::new("/root"), &plain),
  182:             PathBuf::from("/root/sub/plain.txt")
  183:         );
  184:         let root_file = FileHeader::default();
  185:         assert_eq!(
  186:             source_path(Path::new("/root/f"), &root_file),
  187:             PathBuf::from("/root/f")
  188:         );
  189:     }
  190: 
  191:     #[test]
  192:     fn escape_raw_makes_collapsed_names_distinguishable() {
  193:         assert_eq!(escape_raw(b"caf\xe9.txt"), "caf\\xe9.txt");
  194:         assert_eq!(
  195:             escape_raw("caf\u{fffd}.txt".as_bytes()),
  196:             "caf\\xef\\xbf\\xbd.txt"
  197:         );
  198:     }
  199: }
