 1901: /// handing `file` to this function, so stamping through it cannot
 1902: /// reintroduce that race — it can only remove a redundant open.
 1903: fn stamp_streamed_metadata_via_handle(
 1904:     file: &std::fs::File,
 1905:     dst: &Path,
 1906:     header: &FileHeader,
 1907:     config: &FsSinkConfig,
