 1915:         // destinations can refuse mtime updates. Surface via
 1916:         // `log::warn!` so the failure is visible without making
 1917:         // it a hard transfer error. POST_REVIEW_FIXES §1.1.
 1918:         if let Err(e) = filetime::set_file_handle_times(file, None, Some(ft)) {
 1919:             log::warn!("set mtime on {}: {}", dst.display(), e);
 1920:         }
 1921:     }
