 1940: /// Read the local source timestamp at apply time so local copies retain the
 1941: /// precision that the second-granularity wire header cannot represent. The
 1942: /// header value remains a fallback when the source timestamp cannot be read.
 1943: fn source_file_mtime(source: &Path, fallback: Option<FileTime>) -> Option<FileTime> {
 1944:     std::fs::metadata(source)
 1945:         .and_then(|metadata| metadata.modified())
 1946:         .map(FileTime::from_system_time)
 1947:         .ok()
 1948:         .or(fallback)
 1949: }
