 1951: /// Replace wire-derived tar timestamps with local source timestamps. An empty
 1952: /// source root is the transfer-session convention for a wire receive, which
 1953: /// must keep using the timestamp carried by its header.
 1954: fn restamp_local_tar_mtimes(src_root: &Path, files: &mut [super::tar_safety::ExtractedFile]) {
 1955:     if src_root.as_os_str().is_empty() {
 1956:         return;
 1957:     }
 1958:     for file in files {
 1959:         let source = match file.raw.as_deref() {
 1960:             Some(raw) => src_root.join(crate::raw_name::path_from_raw(raw)),
 1961:             None if file.rel.is_empty() => src_root.to_path_buf(),
 1962:             None => src_root.join(&file.rel),
 1963:         };
 1964:         file.mtime = source_file_mtime(&source, file.mtime);
 1965:     }
 1966: }
