 1351: /// The SOURCE session body after establish: spawn the receive half,
 1352: /// run the send half, and map a fault to a peer-notified report. Shared
 1353: /// by [`run_source`] (initiator or direct-responder) and
 1354: /// [`run_responder`] (the daemon SOURCE responder), so the send/receive
 1355: /// choreography is single-sourced.
 1356: async fn drive_source(
 1357:     plan_options: PlanOptions,
 1358:     data_plane_host: Option<String>,
 1359:     instruments: SourceInstruments,
 1360:     mut negotiated: Negotiated,
 1361:     transport: FrameTransport,
 1362:     source: Arc<dyn TransferSource>,
 1363: ) -> Result<TransferSummary> {
 1364:     let phase_trace = bind_session_phase_trace(
 1365:         instruments.session_phase_trace.clone(),
 1366:         &negotiated,
 1367:         SessionPhaseRole::Source,
 1368:     );
 1369:     let small_file_probe = bind_small_file_probe(
 1370:         instruments.small_file_probe.clone(),
 1371:         &negotiated,
 1372:         SessionPhaseRole::Source,
 1373:     );
 1374:     // A SOURCE responder (pull, otp-5b) carries a bound listener to accept
 1375:     // its send sockets on; a SOURCE initiator (push) has none and dials the
 1376:     // grant it received instead. Take it here so the send half owns it.
 1377:     let responder_data_plane = negotiated.responder_data_plane.take();
 1378:     let (mut tx, rx) = transport.split();
 1379:     let sent: Arc<StdMutex<HashMap<String, FileHeader>>> = Arc::default();
 1380:     // Set by the send half immediately before ManifestComplete is handed to
 1381:     // the ordered transport. FrameTx::send enqueues asynchronously, so the
 1382:     // peer can receive the frame and answer before the send future resumes;
 1383:     // setting this after `.await` would reject that legitimate fast reply.
 1384:     // A NeedComplete arriving while this is still false is provably premature
 1385:     // because the source has not yet reached its manifest queue boundary.
 1386:     let manifest_sent = Arc::new(AtomicBool::new(false));
 1387:     let (event_tx, event_rx) = mpsc::unbounded_channel();
 1388:     // Fault side-channel (review otp-8 F1): the in-stream send path
 1389:     // races this signal against blocked record sends; see
 1390:     // `SourceEventSender`.
 1391:     let (fault_tx, fault_rx) = watch::channel(None::<SessionFault>);
 1392:     // AbortOnDrop: an early error return below must abort the receive
 1393:     // half instead of leaking it (same rationale as design-2 / w4-1).
 1394:     let recv_guard = AbortOnDrop::new(tokio::spawn(source_recv_half(
 1395:         rx,
 1396:         Arc::clone(&sent),
 1397:         Arc::clone(&manifest_sent),
 1398:         resume_negotiated(&negotiated.open),
 1399:         // otp-10a: the recv half owns need-batch arrival, which is the
 1400:         // push-direction progress denominator (contract on
 1401:         // `ProgressEvent::ManifestBatch`: "push: need-list batches").
 1402:         instruments.progress.clone(),
 1403:         phase_trace.clone(),
 1404:         small_file_probe.clone(),
 1405:         SourceEventSender {
 1406:             tx: event_tx,
 1407:             fault_signal: fault_tx,
 1408:         },
 1409:     )));
 1410: 
 1411:     let send_result = source_send_half(
 1412:         plan_options,
 1413:         data_plane_host.as_deref(),
 1414:         instruments,
 1415:         &negotiated,
 1416:         responder_data_plane,
 1417:         &mut tx,
 1418:         source,
 1419:         sent,
 1420:         &manifest_sent,
 1421:         event_rx,
 1422:         fault_rx,
 1423:         phase_trace.clone(),
 1424:         small_file_probe,
 1425:     )
 1426:     .await;
 1427:     let mut result = match send_result {
 1428:         Ok(summary) => Ok(summary),
 1429:         Err(report) => {
 1430:             let mut fault = fault_from_report(report);
 1431:             if !fault.peer_notified {
 1432:                 let _ = tx.send(error_frame(&fault)).await;
 1433:                 fault.peer_notified = true;
 1434:             }
 1435:             Err(eyre::Report::new(fault))
 1436:         }
 1437:     };
 1438:     let recv_cleanup = recv_guard.abort_and_join().await;
 1439:     if result.is_ok() {
 1440:         if let Err(err) = recv_cleanup {
 1441:             if !err.is_cancelled() {
 1442:                 result = Err(eyre::Report::new(SessionFault::internal(format!(
 1443:                     "source receive task panicked: {err}"
 1444:                 ))));
 1445:             }
 1446:         }
 1447:     }
 1448:     flush_session_phase_trace(phase_trace.as_ref()).await;
 1449:     result
 1450: }
