 1452: /// Receive half of the source driver: drains the transport for the
 1453: /// whole session so destination sends can never deadlock against a
 1454: /// blocked source send, and routes the destination lane to the send
 1455: /// half. Terminates on summary, error, close, or violation.
 1456: async fn source_recv_half(
 1457:     mut rx: Box<dyn FrameRx>,
 1458:     sent: Arc<StdMutex<HashMap<String, FileHeader>>>,
 1459:     manifest_sent: Arc<AtomicBool>,
 1460:     resume_session: bool,
 1461:     progress: Option<RemoteTransferProgress>,
 1462:     phase_trace: Option<BoundSessionPhaseTrace>,
 1463:     small_file_probe: Option<BoundSmallFileProbe>,
 1464:     events: SourceEventSender,
 1465: ) {
 1466:     let mut need_batch_seq = 0u64;
 1467:     loop {
 1468:         let received = match rx.recv().await {
 1469:             Ok(Some(f)) => f,
 1470:             Ok(None) => {
 1471:                 let _ = events.send(SourceEvent::Fault(SessionFault::internal(
 1472:                     "peer closed before TransferSummary",
 1473:                 )));
 1474:                 return;
 1475:             }
 1476:             Err(err) => {
 1477:                 let _ = events.send(SourceEvent::Fault(SessionFault::internal(format!(
 1478:                     "transport receive failed: {err:#}"
 1479:                 ))));
 1480:                 return;
 1481:             }
 1482:         };
 1483:         match received.frame {
 1484:             Some(Frame::NeedBatch(batch)) => {
 1485:                 if let Some(trace) = &phase_trace {
 1486:                     trace.event(
 1487:                         "need_batch_received",
 1488:                         SessionPhaseFields {
 1489:                             batch: Some(need_batch_seq),
 1490:                             count: Some(batch.entries.len() as u64),
 1491:                             ..Default::default()
 1492:                         },
 1493:                     );
 1494:                     need_batch_seq += 1;
 1495:                 }
 1496:                 for entry in batch.entries {
 1497:                     if entry.resume && !resume_session {
 1498:                         let _ = events.send(SourceEvent::Fault(SessionFault::protocol_violation(
 1499:                             format!(
 1500:                                 "resume-flagged need for '{}' in a session opened without resume",
 1501:                                 entry.relative_path
 1502:                             ),
 1503:                         )));
 1504:                         return;
 1505:                     }
 1506:                     let header = if let Some(probe) = &small_file_probe {
 1507:                         let wait_started = probe.start();
 1508:                         let mut sent = sent.lock().expect("sent-manifest lock poisoned");
 1509:                         let wait = wait_started.elapsed();
 1510:                         let map_op_started = probe.start();
 1511:                         let header = sent.remove(&entry.relative_path);
 1512:                         let map_op = map_op_started.elapsed();
 1513:                         drop(sent);
 1514:                         probe.note_need_resolve(wait, map_op, header.is_some());
 1515:                         header
 1516:                     } else {
 1517:                         sent.lock()
 1518:                             .expect("sent-manifest lock poisoned")
 1519:                             .remove(&entry.relative_path)
 1520:                     };
 1521:                     match header {
 1522:                         Some(h) => {
 1523:                             // The need list is the transfer denominator. Report
 1524:                             // only after resolving the path to its retained
 1525:                             // manifest header, so both file and byte totals are
 1526:                             // exact and an invalid need contributes neither.
 1527:                             if let Some(p) = &progress {
 1528:                                 p.report_manifest_batch(
 1529:                                     1,
 1530:                                     h.size
 1531:                                         .saturating_add(crate::windows_metadata::payload_bytes(&h)),
 1532:                                 );
 1533:                             }
 1534:                             let path = h.relative_path.clone();
 1535:                             let event = if entry.resume {
 1536:                                 SourceEvent::ResumeNeed(h)
 1537:                             } else {
 1538:                                 SourceEvent::Need(h)
 1539:                             };
