 1671: fn validate_source_resize_ack(
 1672:     pending: &data_plane::PendingResize,
 1673:     current_streams: usize,
 1674:     ack: &DataPlaneResizeAck,
 1675: ) -> Result<()> {
 1676:     let effective = ack.effective_stream_count as usize;
 1677:     let expected = if ack.accepted {
 1678:         pending.target_streams as usize
 1679:     } else {
 1680:         current_streams
 1681:     };
 1682:     if effective != expected {
 1683:         let disposition = if ack.accepted { "accepted" } else { "refused" };
 1684:         return Err(eyre::Report::new(SessionFault::protocol_violation(
 1685:             format!(
 1686:                 "{disposition} resize epoch {} reported effective {effective}, expected {expected}",
 1687:                 pending.epoch
 1688:             ),
 1689:         )));
 1690:     }
 1691:     Ok(())
 1692: }
