 1695: async fn source_send_half(
 1696:     plan_options: PlanOptions,
 1697:     data_plane_host: Option<&str>,
 1698:     instruments: SourceInstruments,
 1699:     negotiated: &Negotiated,
 1700:     responder_data_plane: Option<data_plane::ResponderDataPlane>,
 1701:     tx: &mut Box<dyn FrameTx>,
 1702:     source: Arc<dyn TransferSource>,
 1703:     sent: Arc<StdMutex<HashMap<String, FileHeader>>>,
 1704:     manifest_sent: &AtomicBool,
 1705:     mut events: mpsc::UnboundedReceiver<SourceEvent>,
 1706:     mut fault_signal: watch::Receiver<Option<SessionFault>>,
 1707:     phase_trace: Option<BoundSessionPhaseTrace>,
 1708:     small_file_probe: Option<BoundSmallFileProbe>,
 1709: ) -> Result<TransferSummary> {
 1710:     let mut pending: Vec<FileHeader> = Vec::new();
 1711:     let mut resume: ResumeSendState = ResumeSendState::default();
 1712:     let mut need_complete = false;
 1713: 
 1714:     // Data plane (otp-4b/5b): set up the send sockets up front — BEFORE
 1715:     // streaming the manifest — so the peer sees the connections promptly
 1716:     // rather than waiting out a bounded-accept/connect timeout while a long
 1717:     // manifest streams. Which end connects depends on connection role
 1718:     // (otp-5b): a SOURCE **responder** (pull) accepts sockets off its bound
 1719:     // listener; a SOURCE **initiator** (push) dials the grant it received.
 1720:     // Byte direction is the same either way (SOURCE sends), so both yield a
 1721:     // `SourceDataPlane` driven identically below. `None` on both ⇒ the
 1722:     // in-stream carrier (fallback), which needs no early setup.
 1723:     let mut data_plane = match responder_data_plane {
 1724:         // SOURCE responder: accept + send. The DESTINATION initiator
 1725:         // advertised its capacity in the open (the byte RECEIVER advertises,
 1726:         // wherever it initiates); epoch 0 uses the same receiver-bounded
 1727:         // floor as the dial layout and later epochs use the same controller.
 1728:         Some(bound) => Some(
 1729:             data_plane::accept_source_data_plane(
 1730:                 bound,
 1731:                 negotiated.open.receiver_capacity.as_ref(),
 1732:                 Arc::clone(&source),
 1733:                 &instruments,
 1734:                 phase_trace.clone(),
 1735:                 small_file_probe.clone(),
 1736:             )
 1737:             .await?,
 1738:         ),
 1739:         // SOURCE initiator (push, otp-4b): dial the grant if the responder
 1740:         // granted a data plane; else in-stream.
 1741:         None => match &negotiated.accept.data_plane {
 1742:             Some(grant) => {
 1743:                 let host = data_plane_host.ok_or_else(|| {
 1744:                     eyre::Report::new(SessionFault::internal(
 1745:                         "responder granted a TCP data plane but this initiator has no host to dial",
 1746:                     ))
 1747:                 })?;
 1748:                 Some(
 1749:                     data_plane::dial_source_data_plane(
 1750:                         host,
 1751:                         grant,
 1752:                         negotiated.accept.receiver_capacity.as_ref(),
 1753:                         Arc::clone(&source),
 1754:                         &instruments,
 1755:                         phase_trace.clone(),
 1756:                         small_file_probe.clone(),
 1757:                     )
 1758:                     .await?,
 1759:                 )
 1760:             }
 1761:             None => None,
 1762:         },
 1763:     };
 1764: 
 1765:     let proposals = match data_plane.as_mut() {
 1766:         Some(dp) => Some(dp.take_resize_proposals()?),
 1767:         None => None,
 1768:     };
 1769:     let mut resize = SourceResizeState {
 1770:         proposals,
 1771:         pending: None,
 1772:         last_ack: None,
 1773:         #[cfg(test)]
 1774:         membership_test_gate: instruments.dial_membership_test_gate.clone(),
 1775:     };
 1776: 
 1777:     let result: Result<TransferSummary> = async {
 1778:         // Streaming manifest: entries go out as enumeration produces them
 1779:         // (immediate start in every direction — plan §Design 2). The open
 1780:         // carries no source path (the source end owns its local endpoint) but
 1781:         // does carry the include/exclude/size/age filter (otp-6a): only
 1782:         // matching files are manifested and transferred. The filter MUST ride
 1783:         // the wire (not be pre-wrapped by a local caller) because for pull the
 1784:         // SOURCE is the remote daemon responder — it, not the client, owns the
 1785:         // scan. Apply it through the universal `FilteredSource` decorator, the
 1786:         // single filter chokepoint every source impl routes through, rather
 1787:         // than the per-impl `scan(filter)` arg — a source impl is free to
 1788:         // ignore that arg (the since-deleted relay source did; review otp-6a
 1789:         // F1), and the chokepoint makes filtering independent of it. A
 1790:         // default/absent filter scans everything (unchanged from otp-3). Globs
 1791:         // were validated at OPEN (`source_open_validator`), so the conversion
 1792:         // cannot fail on a validated open; map any error to a fault regardless.
 1793:         let scan_source: Arc<dyn TransferSource> = match negotiated.open.filter.as_ref() {
 1794:             Some(spec) if *spec != FilterSpec::default() => {
 1795:                 let filter =
 1796:                     crate::remote::transfer::operation_spec::filter_from_spec(spec.clone())
 1797:                         .map_err(|e| {
 1798:                             eyre::Report::new(SessionFault::internal(format!(
 1799:                                 "invalid filter: {e:#}"
 1800:                             )))
